insert into public.courses(slug,title,description,category,published) values('intro-to-ai','Introduction to Artificial Intelligence','Start here. Learn the main ideas of modern AI.','Basics',true) on conflict do nothing;
insert into public.lessons(id,course_slug,position,title,youtube_id,pdf_url,quiz) values('l1','intro-to-ai',1,'What is Artificial Intelligence?','aircAruvnKk','/pdfs/sample.pdf','[{"q":"What does AI stand for?","options":["Artificial Intelligence","Automatic Internet","Applied Information","Advanced Input"],"answer":0},{"q":"Which one is an example of AI?","options":["A calculator that adds two numbers","A spam filter that learns from emails","A paper book","A light switch"],"answer":1},{"q":"What is a common goal of an AI system?","options":["Perform tasks that usually require human intelligence","Replace every computer program","Make all decisions perfectly","Connect every device to the internet"],"answer":0},{"q":"Which task can an AI system help with?","options":["Recognizing objects in pictures","Making gravity stop","Creating unlimited energy","Guaranteeing every prediction is correct"],"answer":0},{"q":"What is an algorithm?","options":["A step-by-step method for solving a problem","A type of computer screen","A collection of passwords","A device used to store electricity"],"answer":0},{"q":"How can a recommendation system choose what to suggest?","options":["By finding patterns in preferences and activity","By reading a user''s mind","By changing the user''s screen size","By selecting randomly every time"],"answer":0},{"q":"What does speech recognition do?","options":["Turns spoken words into text or commands","Translates text into pictures only","Measures internet speed","Stores files in a folder"],"answer":0},{"q":"What is computer vision?","options":["A field that helps computers interpret images and video","A way to repair computer monitors","A type of computer keyboard","A method for compressing audio"],"answer":0},{"q":"Which statement about AI is true?","options":["AI systems can make mistakes","AI always understands like a person","AI predictions are always unbiased","AI never needs data"],"answer":0},{"q":"What is a chatbot designed to do?","options":["Communicate with people using text or speech","Increase a computer''s battery size","Print documents without a printer","Replace all internet connections"],"answer":0},{"q":"Why should people review important AI-generated information?","options":["AI can produce inaccurate or misleading results","AI cannot display text","Reviewing makes the internet faster","AI results are always encrypted"],"answer":0},{"q":"What does automation mean?","options":["Using technology to carry out tasks with less manual effort","Turning every device into a robot","Removing all software from a computer","Making a task take longer"],"answer":0},{"q":"Which is an example of a rule-based system?","options":["A program that follows conditions written by a person","A notebook with blank pages","A monitor displaying a clock","A cable connecting two devices"],"answer":0},{"q":"What is one way AI differs from traditional software?","options":["Some AI systems learn patterns from examples","AI never uses software","Traditional software cannot follow instructions","AI only works without computers"],"answer":0},{"q":"What does a translation system try to do?","options":["Convert meaning from one language to another","Turn a document into a password","Measure the length of a sentence","Connect a keyboard to a monitor"],"answer":0},{"q":"Why can the quality of training examples matter to AI?","options":["The system may learn patterns reflected in those examples","Examples determine the computer''s screen brightness","More examples always guarantee perfect results","Training examples remove the need for testing"],"answer":0},{"q":"What should be considered when using AI with personal information?","options":["Privacy and how the information is handled","Only the color of the interface","How many browser tabs are open","The size of the computer''s keyboard"],"answer":0},{"q":"Which statement best describes generative AI?","options":["It can create new content such as text, images, or audio","It only stores files without changing them","It is a type of internet cable","It can only sort numbers from smallest to largest"],"answer":0},{"q":"What is a sensible way to use AI as a learning aid?","options":["Use it to explore ideas and check important facts","Copy every answer without reviewing it","Avoid asking questions about its output","Assume it cannot make mistakes"],"answer":0}]') on conflict do nothing;
insert into public.lessons(id,course_slug,position,title,youtube_id,pdf_url,quiz) values('l2','intro-to-ai',2,'Machine Learning Basics','aircAruvnKk',null,'[{"q":"Machine learning lets a computer do what?","options":["Learn from data","Follow fixed rules only","Turn itself off","Print paper"],"answer":0},{"q":"What is training data?","options":["Examples the model learns from","A type of screen","A password","A video format"],"answer":0},{"q":"What is a machine learning model?","options":["A system that has learned patterns from data","A physical model of a computer","A list of internet addresses","A computer''s power cable"],"answer":0},{"q":"What is a feature in a dataset?","options":["An input attribute used to make a prediction","A finished prediction","A type of computer memory","A software license"],"answer":0},{"q":"What is a label in supervised learning?","options":["The known answer associated with a training example","The name of a computer file","A button on a keyboard","The size of a dataset"],"answer":0},{"q":"Why do people split data into training and test sets?","options":["To evaluate how well a model works on examples it did not train on","To make every prediction correct","To remove all data from the model","To avoid measuring model performance"],"answer":0},{"q":"What does a classification model predict?","options":["A category or class","Only a continuous number","The computer''s temperature","The order of files on a disk"],"answer":0},{"q":"What does a regression model typically predict?","options":["A numeric value","A category name only","A sequence of keyboard keys","A network connection"],"answer":0},{"q":"What is overfitting?","options":["When a model memorizes training data and performs poorly on new data","When a model has no training examples","When a computer has too many files","When a dataset is stored online"],"answer":0},{"q":"Why is diverse, representative training data useful?","options":["It can help a model work better across different cases","It guarantees a model has no bias","It removes the need to test a model","It makes the model independent of its task"],"answer":0},{"q":"What does a model do during inference?","options":["Uses what it learned to produce a prediction","Collects the computer''s hardware","Deletes its training data","Writes the program''s source code"],"answer":0}]') on conflict do nothing;
insert into public.lessons(id,course_slug,position,title,youtube_id,pdf_url,quiz) values('l3','intro-to-ai',3,'Neural Networks Explained','aircAruvnKk',null,null) on conflict do nothing;
